WITH deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY amount DESC NULLS LAST, id) AS rn FROM transactions) ranked WHERE rn = 1) SELECT DATE_TRUNC('WEEK', txn_time) AS week_start, DATE_TRUNC('MONTH', txn_time) AS activity_month, MAX(amount) AS max_amount, COUNT(*) FILTER (WHERE merchant = 'Shell') AS shell_rows, RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', txn_time) ORDER BY COUNT(*) FILTER (WHERE merchant = 'Shell') DESC) AS shell_rows_rank FROM deduped GROUP BY week_start, activity_month ORDER BY week_start DESC NULLS LAST
